38	bool TranslateQualifiedNamesMatcher::Data::matchColumnName(std::string_view name, const String & column_name, DataTypePtr column_type)
39	{
40	    if (name.size() < column_name.size())
41	        return false;
42	
43	    if (!name.starts_with(column_name))
44	        return false;
45	
46	    if (name.size() == column_name.size())
47	        return true;
48	
49	    /// In case the type is named tuple, check the name recursively.
50	    if (const DataTypeTuple * type_tuple = typeid_cast<const DataTypeTuple *>(column_type.get()))
51	    {
52	        if (type_tuple->hasExplicitNames() && name.at(column_name.size()) == '.')
53	        {
54	            const Strings & names = type_tuple->getElementNames();
55	            const DataTypes & element_types = type_tuple->getElements();
56	            std::string_view sub_name = name.substr(column_name.size() + 1);
57	            for (size_t i = 0; i < names.size(); ++i)
58	            {
59	                if (matchColumnName(sub_name, names[i], element_types[i]))
60	                {
61	                    return true;
62	                }
63	            }
64	        }
65	    }
66	
67	    return false;
68	}
69	bool TranslateQualifiedNamesMatcher::Data::unknownColumn(size_t table_pos, const ASTIdentifier & identifier) const
70	{
71	    const auto & table = tables[table_pos].table;
72	    const auto & columns = tables[table_pos].columns;
73	
74	    // Remove database and table name from the identifier'name
75	    auto full_name = IdentifierSemantic::extractNestedName(identifier, table);
76	
77	    for (const auto & column : columns)
78	    {
79	        if (matchColumnName(full_name, column.name, column.type))
80	            return false;
81	    }
82	    const auto & hidden_columns = tables[table_pos].hidden_columns;
83	    for (const auto & column : hidden_columns)
84	    {
85	        if (matchColumnName(full_name, column.name, column.type))
86	            return false;
87	    }
88	    return !columns.empty();
89	}
