105	void TranslateQualifiedNamesMatcher::visit(ASTPtr & ast, Data & data)
106	{
107	    if (auto * t = ast->as<ASTIdentifier>())
108	        visit(*t, ast, data);
109	    if (auto * t = ast->as<ASTTableJoin>())
110	        visit(*t, ast, data);
111	    if (auto * t = ast->as<ASTSelectQuery>())
112	        visit(*t, ast, data);
113	    if (auto * node = ast->as<ASTExpressionList>())
114	        visit(*node, ast, data);
115	    if (auto * node = ast->as<ASTFunction>())
116	        visit(*node, ast, data);
117	}
