119	void TranslateQualifiedNamesMatcher::visit(ASTIdentifier & identifier, ASTPtr &, Data & data)
120	{
121	    if (IdentifierSemantic::getColumnName(identifier))
122	    {
123	        String short_name = identifier.shortName();
124	        bool allow_ambiguous = data.join_using_columns.contains(short_name);
125	        if (auto best_pos = IdentifierSemantic::chooseTable(identifier, data.tables, allow_ambiguous))
126	        {
127	            size_t table_pos = *best_pos;
128	            if (data.unknownColumn(table_pos, identifier))
129	            {
130	                String table_name = data.tables[table_pos].table.getQualifiedNamePrefix(false);
131	                throw Exception(ErrorCodes::UNKNOWN_IDENTIFIER, "There's no column '{}' in table '{}'", identifier.name(), table_name);
132	            }
133	
134	            IdentifierSemantic::setMembership(identifier, table_pos);
135	
136	            /// In case if column from the joined table are in source columns, change it's name to qualified.
137	            /// Also always leave unusual identifiers qualified.
138	            const auto & table = data.tables[table_pos].table;
139	            if (table_pos && (data.hasColumn(short_name) || !isValidIdentifierBegin(short_name.at(0))))
140	                IdentifierSemantic::setColumnLongName(identifier, table);
141	            else
142	                IdentifierSemantic::setColumnShortName(identifier, table);
143	        }
144	    }
145	}
