193	void QueryNormalizer::visit(ASTSelectQuery & select, const ASTPtr &, Data & data)
194	{
195	    for (auto & child : select.children)
196	    {
197	        if (needVisitChild(child))
198	            visit(child, data);
199	    }
200	
